UPDATE TB_CHBD001
   SET CP_ID = #{info.cpId}
   	  ,CS_ID = #{info.csId}
   	  ,RCPT_DT = #{info.receiptDate}
   	  ,RCPT_TM = #{info.receiptTime}
   	  ,REP_DT = #{info.repairDate}
   	  ,REP_TM = #{info.repairTime}
   	  ,BD_STAT = #{info.breakdownStatus}
   	  ,UPD_DT = #{info.writer.updateDate}
   	  ,UPD_ID = #{info.writer.updUserId}
 WHERE ID = #{info.id}

mapper.sql:
 WHERE A.CP_ID = B.CP_ID
 	
 	AND A.BD_STAT  = #{searchCond.breakdownStatus}
	
	
 	AND A.CP_ID = #{searchCond.cpId}
	
	
 	AND A.CS_ID = #{searchCond.csId}
	
	
 	AND A.RCPT_DT BETWEEN DATE_FORMAT(#{searchCond.fromDate}, '%Y%m%d%H%i%S') AND  DATE_FORMAT(#{searchCond.toDate}, '%Y%m%d%H%i%S')
	
	
 	AND A.REP_DT = #{searchCond.repairDate}
